 98 │ const SOURCE_TOTAL_MAX = 64 * 1024 * 1024;
 99 │ const ADDED_FILE_MAX = 16 * 1024 * 1024;
100 │ const SIGNIFICANT_LINE_MIN = 8;
101 │ 
102 │ /**
103 │  * The content of the protected files present in the workspace (tracked, untracked or ignored), for recognising a new
104 │  * file that carries it. A new file is carried when it equals a protected file exactly (whatever its size) or shares a
105 │  * significant line with one: a trimmed, non-comment line of at least 8 characters. Files inside `.nexus` take part by
106 │  * exact content only (their lines are structural). When the sources cannot all be read within the limits, every new
107 │  * file counts as carried: nothing is kept because it could not be compared.
108 │  */
109 │ function protectedContent(sources: Array<{ root: string; file: string }>): { carriedBy(dir: string, relative: string): boolean } {
110 │   const hashes = new Set<string>();
111 │   const lines = new Set<string>();
112 │   let complete = true;
113 │   let total = 0;
114 │   for (const { root, file } of sources) {
115 │     const structural = file.split(/[\\/]/).some((seg) => seg.toLowerCase() === ".nexus");
116 │     let size: number;
117 │     try {
118 │       const st = fs.lstatSync(path.join(root, file));
119 │       if (!st.isFile()) continue;
120 │       size = st.size;
121 │     } catch { continue; }
122 │     // A large `.nexus` file (a flight log) is not a credential source: it is left out instead of failing every new file closed.
123 │     if (structural && size > SOURCE_FILE_MAX) continue;
124 │     if (!structural) total += size;
125 │     if (size > SOURCE_FILE_MAX || total > SOURCE_TOTAL_MAX) { complete = false; continue; }
126 │     let data: Buffer;
127 │     try { data = fs.readFileSync(path.join(root, file)); } catch { complete = false; continue; }
128 │     hashes.add(createHash("sha256").update(data).digest("hex"));
129 │     if (structural) continue;
130 │     for (const line of significantLines(data)) lines.add(line);
131 │   }
132 │   return {
133 │     carriedBy(dir: string, relative: string): boolean {
134 │       if (!complete) return true;
135 │       if (hashes.size === 0 && lines.size === 0) return false;
136 │       let data: Buffer;
137 │       try {
138 │         const st = fs.lstatSync(path.join(dir, relative));
139 │         if (!st.isFile()) return false;
140 │         if (st.size > ADDED_FILE_MAX) return true;
141 │         data = fs.readFileSync(path.join(dir, relative));
142 │       } catch { return true; }
143 │       if (hashes.has(createHash("sha256").update(data).digest("hex"))) return true;
144 │       for (const line of significantLines(data)) if (lines.has(line)) return true;
145 │       return false;
146 │     },
147 │   };
148 │ }
