 58 │ /** Drops every `filter` and `diff` assignment (and unset/unspecify forms) from .gitattributes text, macros included. */
 59 │ export function withoutDrivers(text: string): string {
 60 │   return text.split("\n").map((line) => {
 61 │     const trimmed = line.trim();
 62 │     if (!trimmed || trimmed.startsWith("#")) return line;
 63 │     const head = /^("(?:[^"\\]|\\.)*"|\S+)(\s+|$)/.exec(trimmed);
 64 │     if (!head) return line;
 65 │     const rest = trimmed.slice(head[0].length).split(/\s+/).filter(Boolean);
 66 │     return [head[1], ...rest.filter((token) => !/^[-!]?(filter|diff)(=|$)/.test(token))].join(" ");
 67 │   }).join("\n");
 68 │ }
 69 │ const DIFF_FLAGS = ["--no-color", "--no-ext-diff", "--no-textconv", "--no-renames", "--relative"];
 70 │ const MAX_DIFF_PATHS = 2_000;
 71 │ const GIT_MAX_BUFFER = 4 * 1024 * 1024;
 72 │ /** Path listings scale with the repository, not the change, so they get room for very large repositories. */
 73 │ const LISTING_MAX_BUFFER = 256 * 1024 * 1024;
 74 │ /** Paths per `check-attr` call, so its output stays small whatever the repository's size. */
 75 │ const ATTR_BATCH = 1_000;
 76 │ 
 77 │ /**
 78 │  * Refuses (returns why) when a filter or diff driver still applies to any of `files` under the pinned attribute
 79 │  * source, which only `$GIT_DIR/info/attributes` (or a worktree .gitattributes on Git before 2.40) can still assign.
 80 │  * `run` is a pinned git call that takes stdin. Batched so a repository's size never becomes a failure.
 81 │  */
 82 │ export function driverRefusal(run: (args: string[], input: string) => string, files: string[]): string | undefined {
 83 │   for (let start = 0; start < files.length; start += ATTR_BATCH) {
 84 │     const batch = files.slice(start, start + ATTR_BATCH);
 85 │     const checked = run(["check-attr", "-z", "--stdin", "filter", "diff"], `${batch.join("\0")}\0`).split("\0");
 86 │     for (let i = 0; i + 2 < checked.length; i += 3) {
 87 │       const [file, name, value] = [checked[i], checked[i + 1], checked[i + 2]];
 88 │       const safe = value === "unspecified" || value === "unset" || (name === "diff" && value === "set");
 89 │       if (!safe) return `a ${name} driver ('${value}') applies to ${file.slice(0, 80)} outside the worktree's .gitattributes; it is not run`;
 90 │     }
 91 │   }
 92 │   return undefined;
 93 │ }
 94 │ 
 95 │ /** Ignored trees (node_modules, build output) scale with the repository, not the change: about 6 s per 90k files. */
 96 │ const IGNORED_LISTING_TIMEOUT_MS = 180_000;
 97 │ const SOURCE_FILE_MAX = 4 * 1024 * 1024;
 98 │ const SOURCE_TOTAL_MAX = 64 * 1024 * 1024;
 99 │ const ADDED_FILE_MAX = 16 * 1024 * 1024;
100 │ const SIGNIFICANT_LINE_MIN = 8;
101 │ 
102 │ /**
103 │  * The content of the protected files present in the workspace (tracked, untracked or ignored), for recognising a new
104 │  * file that carries it. A new file is carried when it equals a protected file exactly (whatever its size) or shares a
105 │  * significant line with one: a trimmed, non-comment line of at least 8 characters. Files inside `.nexus` take part by
106 │  * exact content only (their lines are structural). When the sources cannot all be read within the limits, every new
107 │  * file counts as carried: nothing is kept because it could not be compared.
108 │  */
109 │ function protectedContent(sources: Array<{ root: string; file: string }>): { carriedBy(dir: string, relative: string): boolean } {
110 │   const hashes = new Set<string>();
111 │   const lines = new Set<string>();
112 │   let complete = true;
113 │   let total = 0;
114 │   for (const { root, file } of sources) {
115 │     const structural = file.split(/[\\/]/).some((seg) => seg.toLowerCase() === ".nexus");
116 │     let size: number;
117 │     try {
118 │       const st = fs.lstatSync(path.join(root, file));
119 │       if (!st.isFile()) continue;
120 │       size = st.size;
121 │     } catch { continue; }
122 │     // A large `.nexus` file (a flight log) is not a credential source: it is left out instead of failing every new file closed.
123 │     if (structural && size > SOURCE_FILE_MAX) continue;
124 │     if (!structural) total += size;
125 │     if (size > SOURCE_FILE_MAX || total > SOURCE_TOTAL_MAX) { complete = false; continue; }
126 │     let data: Buffer;
127 │     try { data = fs.readFileSync(path.join(root, file)); } catch { complete = false; continue; }
128 │     hashes.add(createHash("sha256").update(data).digest("hex"));
129 │     if (structural) continue;
130 │     for (const line of significantLines(data)) lines.add(line);
131 │   }
132 │   return {
133 │     carriedBy(dir: string, relative: string): boolean {
134 │       if (!complete) return true;
135 │       if (hashes.size === 0 && lines.size === 0) return false;
136 │       let data: Buffer;
137 │       try {
138 │         const st = fs.lstatSync(path.join(dir, relative));
139 │         if (!st.isFile()) return false;
140 │         if (st.size > ADDED_FILE_MAX) return true;
141 │         data = fs.readFileSync(path.join(dir, relative));
142 │       } catch { return true; }
143 │       if (hashes.has(createHash("sha256").update(data).digest("hex"))) return true;
144 │       for (const line of significantLines(data)) if (lines.has(line)) return true;
145 │       return false;
146 │     },
147 │   };
148 │ }
149 │ 
150 │ function significantLines(data: Buffer): string[] {
151 │   return data.toString("latin1").split("\n").map((l) => l.trim())
152 │     .filter((l) => l.length >= SIGNIFICANT_LINE_MIN && !l.startsWith("#") && !l.startsWith("//") && /[A-Za-z0-9]/.test(l));
153 │ }
