208 │   const root = path.resolve(workspace);
209 │   let scratch: string | undefined;
210 │   let attrs: { tree: string; objects: string } | undefined;
211 │   // `ownIndex` reads the repository's own index (never written: only listed); everything else uses the scratch index.
212 │   const git = (args: string[], options: { okExit?: number[]; input?: string; maxBuffer?: number; ownIndex?: boolean; timeoutMs?: number } = {}): string => {
213 │     try {
214 │       return execFileSync("git", [...GIT_SAFE, ...args], {
215 │         cwd: root, env: safeGitEnv(options.ownIndex ? undefined : path.join(scratch!, "index"), attrs), encoding: "utf8", stdio: [options.input === undefined ? "ignore" : "pipe", "pipe", "pipe"],
216 │         timeout: options.timeoutMs ?? 30_000, maxBuffer: options.maxBuffer ?? GIT_MAX_BUFFER, ...(options.input === undefined ? {} : { input: options.input }),
217 │       });
218 │     } catch (err: any) {
219 │       if (typeof err?.status === "number" && options.okExit?.includes(err.status) && typeof err.stdout === "string") return err.stdout;
220 │       throw err;
221 │     }
222 │   };
223 │   try {
224 │     scratch = fs.mkdtempSync(path.join(os.tmpdir(), "nexus-candidate-index-"));
