227 │     const security = new SecurityManager(policyWorkspace ?? root);
228 │     // A base read from persisted JSON is resolved as a commit before use: a value shaped like an option is refused.
229 │     const commit = git(["rev-parse", "--verify", "--end-of-options", `${base ?? "HEAD"}^{commit}`]).trim();
230 │     git(["read-tree", "--end-of-options", commit]);
231 │     const listing = (args: string[], ownIndex = false, timeoutMs?: number) => git(["ls-files", "-z", ...args], { maxBuffer: LISTING_MAX_BUFFER, ownIndex, timeoutMs }).split("\0").filter(Boolean);
232 │     // New paths: untracked files git does not ignore, plus files tracked now but not at the base (a force-added file
